 O.joinpath('coding_closure.json').write_text(json.dumps(c,sort_keys=True)+'\n'); m={'schema_version':'async-rbench-closure-v1','case_id':'mab-dependency-unblock-940b9b95f0','source_task_id':'coding:015','event_receipt_sha256':r['receipt_sha256'],'event_consumed':True,'final_revision_sha256':probes['solution.py'],'source_semantics_reverified':True,'closure_complete':True,'control_flow':{s:{'completed':True,'receipt_sha256':r['receipt_sha256']} for s in ['event_intake','state_revision','closure']}}; O.joinpath('decision_manifest.json').write_text(json.dumps(m,sort_keys=True)+'\n')
